#include <assert.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "bootloader.h"
#include "eh_agent_ext.h"
#include "esp_littlefs.h"
#include "esp_flash.h"
#include "esp_ota_ops.h"
#include "esp_system.h"
#include "nvs.h"

// Two blank root commits for each target volume, generated by the Hub.
#include "seeds.h"
#define MIB (1024 * 1024)
static const char *id = "3d86bbb0-0840-486e-9ac5-42a75a9dac23";

// Download transport is outside this fixture; oversize rejection precedes it.
esp_err_t eh_install_op(const cJSON *args, cJSON *data, char *error, size_t len)
{
    abort();
}

static esp_err_t resize(unsigned size, unsigned data, bool erase, const char *seed)
{
    cJSON *args = cJSON_CreateObject(), *result = cJSON_CreateObject();
    cJSON_AddNumberToObject(args, "app_size_bytes", size);
    cJSON_AddNumberToObject(args, "data_size_bytes", data);
    cJSON_AddBoolToObject(args, "erase_littlefs", erase);
    cJSON_AddStringToObject(args, "empty_fs", seed);
    cJSON_AddStringToObject(args, "transfer_id", id);
    char error[160] = {0};
    esp_err_t rc = resize_app(args, result, error, sizeof(error));
    cJSON_Delete(result);
    cJSON_Delete(args);
    return rc;
}

static void check_file(bool allow_format, bool expect_file, bool create_file)
{
    esp_vfs_littlefs_conf_t conf = {.base_path = "/fs", .partition_label = "data",
                                    .format_if_mount_failed = allow_format};
    ESP_ERROR_CHECK(esp_vfs_littlefs_register(&conf));
    FILE *file = fopen("/fs/note", "rb");
    if (expect_file) {
        assert(file && fgetc(file) == 'X');
        fclose(file);
    } else {
        assert(!file && errno == ENOENT);
    }
    if (create_file) {
        file = fopen("/fs/note", "wb");
        assert(file && fputc('X', file) == 'X' && fclose(file) == 0);
    }
    ESP_ERROR_CHECK(esp_vfs_littlefs_unregister("data"));
}

static void check_receipt(unsigned app, unsigned data)
{
    reconcile_resize();
    char *saved = eh_nvs_get_str_alloc(EH_KEY_PENDING);
    assert(saved);
    cJSON *frame = cJSON_Parse(saved);
    free(saved);
    assert(!strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(frame, "name")), "install.done"));
    cJSON *result = cJSON_GetObjectItem(frame, "data");
    assert(cJSON_GetNumberValue(cJSON_GetObjectItem(result, "app_size_bytes")) == app);
    assert(cJSON_GetNumberValue(cJSON_GetObjectItem(result, "data_size_bytes")) == data);
    assert(!strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(result, "transfer_id")), id));
    cJSON_Delete(frame);
    ESP_ERROR_CHECK(eh_nvs_erase(EH_KEY_PENDING));
}

void app_main(void)
{
    ESP_ERROR_CHECK(eh_nvs_init());
    unsigned phase = eh_nvs_get_u8("resize_probe", 0);
    const esp_partition_t *app = esp_partition_find_first(ESP_PARTITION_TYPE_APP, ESP_PARTITION_SUBTYPE_APP_OTA_2, "app");
    const esp_partition_t *data = esp_partition_find_first(ESP_PARTITION_TYPE_DATA, ESP_PARTITION_SUBTYPE_DATA_LITTLEFS, "data");
    assert(app && data && app->address + app->size == data->address);
    uint32_t flash;
    ESP_ERROR_CHECK(esp_flash_get_size(NULL, &flash));
    const char *small = flash == 8 * MIB ? seed_small : seed_legacy_small;
    const char *large = flash == 8 * MIB ? seed_large : seed_legacy_large;
    unsigned small_fs = flash - app->address - 5 * MIB;
    unsigned large_fs = small_fs + MIB;
    if (phase == 0) {
        assert(app->size == 4 * MIB);
        char error[160] = {0};
        cJSON *args = cJSON_Parse("{\"kind\":\"app\",\"image_size\":4194305}"), *result = cJSON_CreateObject();
        assert(launcher_install(args, result, error, sizeof(error)) == ESP_ERR_INVALID_SIZE);
        assert(strstr(error, "4194305") && strstr(error, "4194304"));
        cJSON_Delete(args);
        cJSON_Delete(result);
        check_file(true, false, true);
        assert(resize(5 * MIB, small_fs, false, small) != ESP_OK);
        assert(resize(5 * MIB, small_fs, true, large) != ESP_OK);
        assert(resize(65536, data->size + app->size - 65536, true, small) != ESP_OK);
        check_file(false, true, false);
        ESP_ERROR_CHECK(resize(5 * MIB, small_fs, true, small));
    } else {
        assert(phase <= 2 && app->size == (phase == 1 ? 5 : 4) * MIB);
        assert(esp_ota_get_partition_description(app, &(esp_app_desc_t){0}) == ESP_OK);
        check_receipt(app->size, data->size);
        check_file(false, false, true);
        ESP_ERROR_CHECK(resize(app->size, data->size, false, ""));
        check_file(false, true, false);
        if (phase == 1) ESP_ERROR_CHECK(resize(4 * MIB, large_fs, true, large));
    }
    ESP_ERROR_CHECK(eh_nvs_set_u8("resize_probe", phase + 1));
    printf("RESIZE PROBE PASS %u\n", phase);
    fflush(stdout);
}
